def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    memo: dict[str, int | str] = {}
    visiting: set[str] = set()

    def is_err(v) -> bool:
        return isinstance(v, str)

    def div_trunc(a: int, b: int):
        if b == 0:
            return "#DIV/0!"
        sign = -1 if (a < 0) ^ (b < 0) else 1
        return sign * (abs(a) // abs(b))

    def compare(a: int, op: str, b: int) -> bool:
        if op == "=":
            return a == b
        if op == "<>":
            return a != b
        if op == "<":
            return a < b
        if op == "<=":
            return a <= b
        if op == ">":
            return a > b
        return a >= b

    def eval_cell(name: str):
        if name in memo:
            return memo[name]
        if name not in cells:
            return 0
        if name in visiting:
            return "#CYCLE!"
        visiting.add(name)
        try:
            raw = cells[name].strip()
            if raw.startswith("="):
                val = eval_ast(parse_formula(raw[1:]))
            else:
                val = int(raw)
        finally:
            visiting.remove(name)
        memo[name] = val
        return val

    def eval_range(c1: int, r1: int, c2: int, r2: int):
        out = []
        for r in range(min(r1, r2), max(r1, r2) + 1):
            for c in range(min(c1, c2), max(c1, c2) + 1):
                name = chr(ord("A") + c) + str(r)
                if name not in cells:
                    continue
                v = eval_cell(name)
                if is_err(v):
                    return v
                out.append(v)
        return out

    def eval_ast(node):
        kind = node[0]
        if kind == "num":
            return node[1]
        if kind == "cell":
            return eval_cell(node[1])
        if kind == "neg":
            v = eval_ast(node[1])
            return v if is_err(v) else -v
        if kind == "bin":
            op, left, right = node[1], node[2], node[3]
            lv = eval_ast(left)
            if is_err(lv):
                return lv
            rv = eval_ast(right)
            if is_err(rv):
                return rv
            if op == "+":
                return lv + rv
            if op == "-":
                return lv - rv
            if op == "*":
                return lv * rv
            return div_trunc(lv, rv)
        if kind in ("sum", "min", "max"):
            vals = []
            for arg in node[1]:
                if arg[0] == "range":
                    got = eval_range(arg[1], arg[2], arg[3], arg[4])
                    if is_err(got):
                        return got
                    vals.extend(got)
                else:
                    v = eval_ast(arg[1])
                    if is_err(v):
                        return v
                    vals.append(v)
            if kind == "sum" or not vals:
                return sum(vals)
            return min(vals) if kind == "min" else max(vals)
        left, op, right, then_b, else_b = node[1], node[2], node[3], node[4], node[5]
        lv = eval_ast(left)
        if is_err(lv):
            return lv
        rv = eval_ast(right)
        if is_err(rv):
            return rv
        return eval_ast(then_b if compare(lv, op, rv) else else_b)

    def parse_formula(src: str):
        s = src
        n = len(s)
        i = 0

        def skip():
            nonlocal i
            while i < n and s[i] == " ":
                i += 1

        def peek() -> str:
            skip()
            return s[i] if i < n else ""

        def expr():
            left = term()
            while peek() in "+-":
                op = s[i]
                i_inc = 1
                nonlocal i
                i += i_inc
                right = term()
                left = ("bin", op, left, right)
            return left

        def term():
            nonlocal i
            left = unary()
            while peek() in "*/":
                op = s[i]
                i += 1
                right = unary()
                left = ("bin", op, left, right)
            return left

        def unary():
            nonlocal i
            if peek() == "-":
                i += 1
                return ("neg", unary())
            return atom()

        def atom():
            nonlocal i
            skip()
            if s[i] == "(":
                i += 1
                node = expr()
                skip()
                i += 1
                return node
            if s[i].isdigit():
                j = i
                while j < n and s[j].isdigit():
                    j += 1
                num = int(s[i:j])
                i = j
                return ("num", num)
            j = i + 1
            while j < n and s[j].isalpha():
                j += 1
            word = s[i:j]
            if word in ("SUM", "MIN", "MAX", "IF"):
                i = j
                return func(word)
            while j < n and s[j].isdigit():
                j += 1
            name = s[i:j]
            i = j
            return ("cell", name)

        def func(word: str):
            nonlocal i
            skip()
            i += 1
            if word == "IF":
                left = expr()
                op = cmpop()
                right = expr()
                comma()
                then_b = expr()
                comma()
                else_b = expr()
                skip()
                i += 1
                return ("if", left, op, right, then_b, else_b)
            args = [arg()]
            while peek() == ",":
                i += 1
                args.append(arg())
            skip()
            i += 1
            return (word.lower(), args)

        def comma():
            nonlocal i
            skip()
            i += 1

        def cmpop() -> str:
            nonlocal i
            skip()
            two = s[i : i + 2]
            if two in ("<>", "<=", ">="):
                i += 2
                return two
            i += 1
            return two[0]

        def looks_range() -> bool:
            skip()
            k = i
            if k >= n or not s[k].isalpha() or (k + 1 < n and s[k + 1].isalpha()):
                return False
            k += 1
            if k >= n or not s[k].isdigit():
                return False
            while k < n and s[k].isdigit():
                k += 1
            while k < n and s[k] == " ":
                k += 1
            return k < n and s[k] == ":"

        def read_cell() -> str:
            nonlocal i
            skip()
            j = i + 1
            while j < n and s[j].isdigit():
                j += 1
            name = s[i:j]
            i = j
            return name

        def arg():
            nonlocal i
            if looks_range():
                a = read_cell()
                skip()
                i += 1
                b = read_cell()
                return (
                    "range",
                    ord(a[0]) - ord("A"),
                    int(a[1:]),
                    ord(b[0]) - ord("A"),
                    int(b[1:]),
                )
            return ("expr", expr())

        return expr()

    return {name: eval_cell(name) for name in cells}
